+package main
+
+import (
+	"fmt"
+	runewidth "github.com/mattn/go-runewidth"
+)
+
+const (
+	shortenSuffix = "..."
+	prefix        = " "
+	suffix        = " "
+)
+
+func formatTextsOriginal(o []string, maxWidth int) (new []string, width int) {
+	l := len(o)
+	n := make([]string, l)
+
+	lenPrefix := runewidth.StringWidth(prefix)
+	lenSuffix := runewidth.StringWidth(suffix)
+	lenShorten := runewidth.StringWidth(shortenSuffix)
+	
+	// Calculate initial width
+	initialWidth := 0
+	for i := 0; i < l; i++ {
+		w := runewidth.StringWidth(o[i])
+		if initialWidth < w {
+			initialWidth = w
+		}
+	}
+
+	if initialWidth == 0 {
+		return n, 0
+	}
+	if min := lenPrefix + lenSuffix + lenShorten; min >= maxWidth {
+		return n, 0
+	}
+	if lenPrefix+initialWidth+lenSuffix > maxWidth {
+		initialWidth = maxWidth - lenPrefix - lenSuffix
+	}
+
+	width = initialWidth
+	for i := 0; i < l; i++ {
+		x := runewidth.StringWidth(o[i])
+		if x <= width {
+			spaces := ""
+			for j := 0; j < width-x; j++ {
+				spaces += " "
+			}
+			n[i] = prefix + o[i] + spaces + suffix
+		} else if x > width {
+			truncated := runewidth.Truncate(o[i], width, shortenSuffix)
+			// Original buggy behavior - doesn't adjust width after FillRight
+			n[i] = prefix + runewidth.FillRight(truncated, width) + suffix
+		}
+	}
+	return n, lenPrefix + width + lenSuffix // Returns theoretical width, not actual width
+}
+
+func main() {
+	// Test case from the issue description
+	inputs := []string{
+		"This is a long suggestion",
+		"Another long suggestion",
+		"Yet another long one",
+	}
+	
+	fmt.Println("Original behavior with max width of 20:")
+	formatted, totalWidth := formatTextsOriginal(inputs, 20)
+	
+	for i, s := range formatted {
+		actualWidth := runewidth.StringWidth(s)
+		fmt.Printf("'%s' (actual width: %d)\n", s, actualWidth)
+		if actualWidth != totalWidth {
+			fmt.Printf("  MISMATCH: expected %d, got %d\n", totalWidth, actualWidth)
+		}
+	}
+	fmt.Printf("Returned total width: %d\n", totalWidth)
+}
