+	for i := 0; i < num; i++ {
+		left[i] = suggests[i].Text
+	}
+
+	left, leftWidth := formatTexts(left, max, leftPrefix, leftSuffix)
+	if leftWidth == 0 {
+		return []struct{ Text string }{}, 0
+	}
+
+	for i := 0; i < num; i++ {
+		new[i] = struct{ Text string }{Text: left[i]}
+	}
+	return new, leftWidth
