+	if lenPrefix+initialWidth+lenSuffix > maxWidth {
+		initialWidth = maxWidth - lenPrefix - lenSuffix
+	}
+
+	width = initialWidth
+	for i := 0; i < l; i++ {
+		x := runewidth.StringWidth(o[i])
+		if x <= width {
+			spaces := ""
+			for j := 0; j < width-x; j++ {
+				spaces += " "
+			}
+			n[i] = prefix + o[i] + spaces + suffix
+		} else if x > width {
+			truncated := runewidth.Truncate(o[i], width, shortenSuffix)
+			filled := runewidth.FillRight(truncated, width)
+			n[i] = prefix + filled + suffix
+			// Update width to actual width of filled text to ensure consistent sizing
+			if runewidth.StringWidth(filled) != width {
+				width = runewidth.StringWidth(filled)
+			}
+		}
+	}
+	return n, lenPrefix + width + lenSuffix
+}
